#pragma once

#include <cstdint>
#include <span>

// Compact Unicode data generated by generate_tables.py (see UnicodeTables.cpp).
namespace sloptube::app::text {

// Contextual presentation forms of an Arabic letter; 0 where the form does not exist.
struct ArabicForms {
    char16_t base;
    char16_t isolated;
    char16_t final;
    char16_t initial;
    char16_t medial;
};

// Lam followed by `alef` ligates into one glyph.
struct LamAlef {
    char16_t alef;
    char16_t isolated;
    char16_t final;
};

// Runs of equal bidi class, sorted: (first code point << 4) | BidiClass.
extern const std::span<const std::uint32_t> kBidiRuns;
// Sorted by base.
extern const std::span<const ArabicForms> kArabicForms;
extern const std::span<const LamAlef> kLamAlef;

} // namespace sloptube::app::text
